INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16018, 'ពេលជួបគ្រូ ឬភ្ញៀវនៅទីធ្លា សិស្សត្រូវ ៖', NULL, '["ក្រោកឈរស្ងាត់ និងលើកដៃសំពះដោយទន់ភ្លន់", "គ្រាន់តែញញឹមហើយដើរផុត", "អង្គុយនៅនឹងកន្លែង", "ហៅទូរសព្ទ"]', 0, NULL, 1, 'mcq', 'ក៤ ៖ ក្រោកឈរ សំពះទន់ភ្លន់។', 'បទបញ្ជាផ្ទៃក្នុង', 'easy', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
