INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16044, 'អវត្តមានប្រឡងដោយមានច្បាប់ បេសកកម្មសាលា ទទួលពិន្ទុ ៖', NULL, '["សូន្យ", "ស្មើពិន្ទុខ្ពស់ជាងគេដក ០៥ ឬតាមគណៈគ្រប់គ្រង", "ពិន្ទុពេញ", "ស្មើពិន្ទុទាបជាងគេ"]', 1, NULL, 3, 'mcq', 'បេសកកម្មចាត់តាំងដោយសាលា ៖ ខ្ពស់ជាងគេ − ០៥។', 'បទបញ្ជាផ្ទៃក្នុង', 'hard', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16045, 'ឈប់មានច្បាប់និងឥតច្បាប់លើស ៣០ ដង ឬកិច្ចសន្យាលើកទី ៣ នឹង ៖', NULL, '["រៀនត្រួតថ្នាក់តែប៉ុណ្ណោះ", "បាត់បង់សិទ្ធិរៀននៅសាលារៀនជំនាន់ថ្មី", "បន្ថយមួយឆមាស", "ណែនាំម្តងទៀត"]', 1, NULL, 3, 'mcq', 'ករណីទី ២ ៖ លើស ៣០ ដង ឬកិច្ចសន្យាលើកទី ៣។', 'បទបញ្ជាផ្ទៃក្នុង', 'hard', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16046, 'លុបបេក្ខភាពក៏ព្រោះគ្មានពិន្ទុមធ្យមភាគឆមាស បើឈប់ឥតច្បាប់ពេលប្រឡងឆមាស ៖', NULL, '["មុខវិជ្ជាណាមួយ", "តែ ៥ មុខ", "គ្រប់មុខវិជ្ជា", "តែគណិត"]', 0, NULL, 3, 'mcq', 'ករណីទី ២ ៖ ឥតច្បាប់មុខវិជ្ជាណាមួយ។', 'បទបញ្ជាផ្ទៃក្នុង', 'hard', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16047, 'សិស្សស្រីពាក់ខ្សែក ផាត់ម្សៅ និងស្លៀកសំពត់ឆែក។ តើខុសប្រការណា?', NULL, '["ប្រការ ៦ សុំច្បាប់", "ប្រការ ១ ឃ ហាមតុបតែង និងសំពត់ឆែក/ខ្លី", "តារាងម៉ោងទី ១", "ប្រការ ៨ បេក្ខភាព"]', 1, NULL, 3, 'mcq', 'ហាមសំពត់ឆែក អលង្ការ ផាត់ម្សៅ។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16048, 'សិស្សមកដល់ ៧:៤០ ខណៈម៉ោងទី ១ ចាប់ ៧:៣០។ ត្រូវចាត់ទុកថា ៖', NULL, '["អវត្តមាន", "មិនគិតព្រោះតិចជាង ១៥ នាទី", "យឺតតែមានវត្តមាន", "មានច្បាប់ស្វ័យប្រវត្តិ"]', 0, NULL, 3, 'mcq', 'ចូលក្រោយម៉ោងកំណត់ = អវត្តមាន។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16049, 'សិស្សឈឺ មាតាបិតាសុំច្បាប់តាម APP ប៉ុន្តែខកខានប្រឡងខែ (មូលហេតុផ្ទាល់ខ្លួន)។ ពិន្ទុគឺ ៖', NULL, '["ខ្ពស់ជាងគេដក ៥", "ស្មើពិន្ទុទាបជាងគេក្នុងថ្នាក់តាមមុខនោះ", "ពិន្ទុពេញ", "សូន្យ"]', 1, NULL, 3, 'mcq', 'មានច្បាប់ + ផ្ទាល់ខ្លួន = ពិន្ទុទាបជាងគេ។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, chapter, params, cancelled) VALUES (10, 16050, 'សិស្សចង់ចេញមុនម៉ោងទី ៤ ព្រោះមានណាត់ពេទ្យ។ គ្រូមុខវិជ្ជាអនុញ្ញាតឱ្យទៅ។ តើត្រូវទេ?', NULL, '["ត្រូវ បើប្រធានថ្នាក់យល់ព្រម", "ត្រូវ ព្រោះគ្រូមុខវិជ្ជាអនុញ្ញាតហើយ", "មិនត្រូវ ៖ តែគណៈគ្រប់គ្រងអនុញ្ញាតបាន ហើយត្រូវមាតាបិតាសុំ", "ត្រូវ បើមិត្តនាំទៅ"]', 2, NULL, 3, 'mcq', 'គ្រូបង្រៀនមិនមានសិទ្ធិអនុញ្ញាតចេញមុនម៉ោង។', 'បទបញ្ជាផ្ទៃក្នុង', 'pisa', 1, '7', 'បទបញ្ជាផ្ទៃក្នុង', 'តម្រង់ទិសសិស្ស NGS ២០២៦-២០២៧', NULL, 0);
